// One request per video, all in one crawl.
const cfg = $('Settings').first().json;

// Accepts a watch URL, a youtu.be link or a bare eleven-character ID, and
// normalises all three to the watch URL the dataset expects.
function videoId(raw) {
  const s = String(raw || '').trim();
  if (/^[A-Za-z0-9_-]{11}$/.test(s)) return s;
  const m = s.match(/(?:v=|youtu\.be\/|\/shorts\/|\/embed\/)([A-Za-z0-9_-]{11})/);
  return m ? m[1] : null;
}

const ids = [...new Set(
  String(cfg.video_urls || '')
    .split(/[,\n]/)
    .map(videoId)
    .filter(Boolean)
)].slice(0, Math.max(1, Number(cfg.max_videos) || 8));

if (!ids.length) {
  throw new Error(
    'No usable video URLs in Settings. Expected YouTube watch links, one per ' +
    'line or comma separated, like https://www.youtube.com/watch?v=ERarYs2KVPI'
  );
}

// sort_by is case sensitive and takes exactly two values. Anything else comes
// back as a bare "This value is not allowed" with no list of what is allowed,
// so it is normalised here rather than trusted from Settings.
const wanted = String(cfg.sort_by || '').trim().toLowerCase();
const sort = wanted.startsWith('new') ? 'Newest first' : 'Top comments';

// Left out, the API returns ONE comment after 164 seconds. Measured. This is
// the single most consequential field on the request.
const per = Math.min(200, Math.max(10, Number(cfg.comments_per_video) || 40));

return [{
  json: {
    ids,
    sort,
    per,
    payload: ids.map((id) => ({
      url: 'https://www.youtube.com/watch?v=' + id,
      num_of_comments: per,
      sort_by: sort,
    })),
  },
}];

const p = $json || {};

if (p.error) {
  throw new Error(
    'Bright Data refused the crawl: ' + JSON.stringify(p.error).slice(0, 300)
  );
}

const status = String(p.status || '');

if (status === 'failed') {
  throw new Error(
    'The crawl failed at Bright Data. Snapshot ' + (p.snapshot_id || 'unknown') +
    '. Check the dataset in the Bright Data dashboard before rerunning.'
  );
}

// $runIndex is how many times this node has already run in this execution, so
// it is the poll count. Without a cap a snapshot that never finishes keeps the
// execution alive until the instance is restarted.
const polls = $runIndex + 1;
const MAX_POLLS = 16;

if (status !== 'ready' && polls >= MAX_POLLS) {
  throw new Error(
    'The crawl was still running after ' + polls + ' checks, about ' +
    (polls * 10) + ' seconds. Three videos at 40 comments each took 23 seconds ' +
    'when this was measured, so either max_videos is high or Bright Data is ' +
    'backed up. Snapshot ' + (p.snapshot_id || 'unknown')
  );
}

// error_codes counts the videos that came back empty. The per-video reason is
// on the rows themselves, which is where the reader picks it up.
return [{
  json: {
    snapshot_id: p.snapshot_id,
    status,
    ready: status === 'ready',
    records: p.records || 0,
    error_codes: p.error_codes || null,
    polls,
  },
}];

// The results array is not all comments. With include_errors on, a video that
// returned nothing arrives as a row carrying `error`, `error_code` and `input`
// and no comment_text or video_id at all - and in the measured sample it was
// the FIRST row. Anything that reads rows[0] to learn the shape learns the
// wrong one, and anything that maps blindly gets the string "undefined" as a
// comment.
const plan = $('Build The Video List').first().json;
const cfg = $('Settings').first().json;
const minChars = Math.max(10, Number(cfg.min_comment_chars) || 40);
const rows = $input.all().map((i) => i.json).filter(Boolean);

const failures = rows
  .filter((r) => r.error || !r.comment_text)
  .map((r) => ({
    video_id: null,
    video_url: ((r.input || {}).url) || null,
    // dead_page on this dataset means "no comments", not "no video". The
    // message is literally "No comments exists on the video", which is an
    // ordinary state for a new upload.
    reason: String(r.error || 'the row carried no comment text'),
  }));

const comments = rows
  .filter((r) => r.comment_text && r.video_id)
  .map((r) => {
    const text = String(r.comment_text).replace(/\s+/g, ' ').trim();
    return {
      comment_id: r.comment_id,
      video_id: r.video_id,
      video_url: r.url,
      author: r.username || null,
      text,
      chars: text.length,
      // Likes are the weight. `replies` was 1 on 32 of 51 rows in the measured
      // sample, so it carries almost no information; likes ran 0 to 463.
      likes: Number(r.likes) || 0,
      // Kept as it arrives and never parsed. `date` is prose - "10 months ago",
      // sometimes "1 year ago (edited)" - and `date_iso` is computed from that
      // prose, landing exactly ten months before the scrape to the second. It
      // is not a posting date and nothing here sorts or filters by it.
      age_text: r.date || null,
      usable: text.length >= minChars,
    };
  });

// Deduplicated on the comment id: the same comment can be returned twice when a
// video is listed under two URLs that resolve to it.
const seen = new Set();
const unique = comments.filter((c) => {
  if (seen.has(c.comment_id)) return false;
  seen.add(c.comment_id);
  return true;
});

const gotVideos = new Set(unique.map((c) => c.video_id));
const silent = plan.ids.filter((id) => !gotVideos.has(id));

// Never empty, so the branch below always runs. A crawl where every video came
// back silent still has to produce a report saying so.
return [{
  json: {
    comments: unique.filter((c) => c.usable),
    dropped_short: unique.filter((c) => !c.usable).length,
    failures,
    silent_videos: silent,
    videos_asked: plan.ids.length,
    videos_read: gotVideos.size,
  },
}];

// The classifying, in code. Six rule sets, each a list of phrases that a buyer
// actually writes. A comment can land in more than one - "too expensive and it
// keeps crashing" is two objections in one sentence, and forcing a single
// category would lose one of them.
const cfg = $('Settings').first().json;
// A single-item input by construction: Read The Comments returns one bundle
// holding every comment, precisely so a crawl where every video came back
// silent still produces an item and this branch still runs.
const bundle = $input.first().json;

const RULES = {
  price: /\b(too expensive|expensive|overpriced|not worth (?:the|it)|price|pricing|paywall|subscription|per month|per seat|refund|cancel(?:led|ing)? my|free tier|charge(?:s|d)? me)\b/i,
  performance: /\b(slow|sluggish|laggy?|lag\b|crash(?:es|ed|ing)?|freez(?:e|es|ing)|buggy|bugs?\b|glitch|broken|unusable|offline|sync(?:ing)? (?:issue|problem)|load(?:s|ing)? forever)\b/i,
  complexity: /\b(confusing|overwhelming|too complicated|complicated|learning curve|clunky|bloated|takes? (?:too )?(?:long|forever) to set ?up|set ?up time|fiddly|hard to (?:use|learn)|not intuitive)\b/i,
  missing: /\b(i wish|wish it|why can'?t|can'?t (?:do|add|export|see)|cannot|doesn'?t (?:have|support|do)|does not (?:have|support)|no (?:way|option) to|missing|lacks?|lacking|need(?:s)? (?:it )?to)\b/i,
  switching: /\b(switch(?:ed|ing)? (?:to|back)|mov(?:ed|ing) to|migrat(?:ed|ing) to|replac(?:ed|ing) .{0,20}with|stick(?:ing)? with|went back to|gave up on|ditched|dropped it for|instead of)\b/i,
  trust: /\b(privacy|my data|data (?:is|are)|security|encrypt|train(?:ed|ing) (?:on|their)|own(?:ership)? of my|lock(?:ed)?[- ]in|vendor lock|export my|shut(?:s)? down|acquired)\b/i,
};

const LABELS = {
  price: 'Price and packaging',
  performance: 'Performance and reliability',
  complexity: 'Complexity and setup',
  missing: 'Missing capability',
  switching: 'Leaving for something else',
  trust: 'Trust, data and lock-in',
};

// A named alternative is the most useful thing in the whole comment section and
// the only one a competitor list cannot produce, because it is whatever the
// person actually typed. The capture starts after the leaving phrase and takes
// the words that follow, so it finds products nobody thought to watch.
const SWITCH_TO = /\b(?:switch(?:ed|ing)? to|mov(?:ed|ing) to|migrat(?:ed|ing) to|went back to|stick(?:ing)? with|dropped it for|replaced it with)\s+([A-Za-z][\w.+-]*(?:\s+[A-Za-z][\w.+-]*){0,2})/i;

// Words that follow a leaving phrase without naming anything - "switched to
// using", "moved to a spreadsheet". Left in, they become the top competitor.
const NOT_A_PRODUCT = new Set([
  'using', 'use', 'a', 'an', 'the', 'my', 'another', 'something', 'it', 'them',
  'this', 'that', 'paper', 'other', 'anything', 'nothing', 'plain', 'just',
]);

function alternativeIn(text) {
  const m = text.match(SWITCH_TO);
  if (!m) return null;
  const words = m[1].split(/\s+/).filter((w) => !NOT_A_PRODUCT.has(w.toLowerCase()));
  if (!words.length) return null;
  // Product names are capitalised in practice; a run of lowercase words after
  // "switched to" is a sentence continuing, not a product.
  const named = words.filter((w) => /^[A-Z]/.test(w));
  const pick = (named.length ? named : words).slice(0, 3).join(' ');
  return pick.replace(/[.,!?;:]+$/, '').trim() || null;
}

const brand = String(cfg.your_brand || '').trim().toLowerCase();

const scored = (bundle.comments || []).map((c) => {
  const themes = Object.keys(RULES).filter((k) => RULES[k].test(c.text));
  const alternative = themes.includes('switching') ? alternativeIn(c.text) : null;
  return {
    ...c,
    themes,
    theme_labels: themes.map((t) => LABELS[t]),
    alternative,
    // Whether your own product turned up in somebody else's comment section,
    // which is a different finding from an objection and worth its own line.
    mentions_you: !!brand && c.text.toLowerCase().includes(brand),
    is_objection: themes.length > 0,
  };
});

return scored.map((json) => ({ json }));

// The counting, also in code. The model below writes sentences and computes
// nothing, so a garbled reply costs the prose and never the numbers.
const cfg = $('Settings').first().json;
const bundle = $('Read The Comments').first().json;
const rows = $input.all().map((i) => i.json);
const objections = rows.filter((r) => r.is_objection);
const quotesPerTheme = Math.max(2, Number(cfg.quotes_per_theme) || 3);

const LABELS = {
  price: 'Price and packaging',
  performance: 'Performance and reliability',
  complexity: 'Complexity and setup',
  missing: 'Missing capability',
  switching: 'Leaving for something else',
  trust: 'Trust, data and lock-in',
};

const themes = Object.keys(LABELS).map((key) => {
  const set = objections
    .filter((r) => r.themes.includes(key))
    // Weighted by likes, because a complaint with 463 of them is a different
    // fact from the same words with none.
    .sort((a, b) => b.likes - a.likes);
  return {
    key,
    label: LABELS[key],
    comments: set.length,
    likes: set.reduce((a, r) => a + r.likes, 0),
    // Share of the objections, not of all comments. "38% of complaints are
    // about price" and "38% of the comment section is about price" are
    // different claims and only the first one is true here. The shares sum past
    // 100 because a comment can raise more than one objection, which the digest
    // says out loud rather than leaving the reader to notice.
    share_pct: objections.length ? Math.round((set.length / objections.length) * 100) : 0,
    candidates: set,
  };
}).filter((t) => t.comments > 0)
  .sort((a, b) => b.likes - a.likes || b.comments - a.comments);

// Quotes are assigned after the ranking, not inside it. One comment can carry
// three objections - "too expensive and it keeps crashing so I moved to X" is
// all three - and picking each theme's loudest comment independently printed
// the same 184-like quote under two headings, which reads as a broken report
// rather than as a comment that said two things. The biggest theme gets first
// claim; a theme whose every comment is already spoken for reuses its own
// loudest rather than showing nothing.
const spoken = new Set();
themes.forEach((t) => {
  const fresh = t.candidates.filter((r) => !spoken.has(r.comment_id));
  const pick = (fresh.length ? fresh : t.candidates).slice(0, quotesPerTheme);
  pick.forEach((r) => spoken.add(r.comment_id));
  t.quotes = pick.map((r) => ({ likes: r.likes, text: r.text.slice(0, 260), url: r.video_url }));
  delete t.candidates;
});

// Whatever people actually named, counted. Not a watchlist - a product nobody
// thought to track is exactly the one worth knowing about.
// Title-cased for display only. People type "apple notes" and "Craft" in the
// same comment section, and a list that mixes the two reads as two different
// kinds of fact. The match is still on what they wrote.
const display = (name) =>
  String(name).split(/\s+/).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');

const tally = {};
objections.filter((r) => r.alternative).forEach((r) => {
  const k = r.alternative.toLowerCase();
  tally[k] = tally[k] || { name: display(r.alternative), mentions: 0, likes: 0, quote: null };
  tally[k].mentions += 1;
  tally[k].likes += r.likes;
  if (!tally[k].quote || r.likes > tally[k].quote.likes) {
    tally[k].quote = { likes: r.likes, text: r.text.slice(0, 220) };
  }
});

return [{
  json: {
    themes,
    alternatives: Object.values(tally).sort((a, b) => b.mentions - a.mentions || b.likes - a.likes).slice(0, 8),
    total_comments: rows.length,
    objection_count: objections.length,
    objection_share_pct: rows.length ? Math.round((objections.length / rows.length) * 100) : 0,
    mentions_of_you: objections.filter((r) => r.mentions_you).length,
    videos_asked: bundle.videos_asked,
    videos_read: bundle.videos_read,
    dropped_short: bundle.dropped_short,
    failures: bundle.failures,
    silent_videos: bundle.silent_videos,
  },
}];

