// The model wrote lines, not JSON. A line format survives a model that adds a
// preamble, drops a field or reorders the output, and an unparseable reply here
// costs the sentences and leaves every count intact.
const b = $('Rank The Themes').first().json;
// A single-item input by construction: the chain above answers once, because
// Rank The Themes emits exactly one row for the whole run.
const reading = String(($input.first().json || {}).text || '');
const today = new Date().toISOString().slice(0, 10);

// "1 comments, 1 likes" is the kind of thing a reviewer notices before the
// finding is.
const plural = (n, one, many) => n + ' ' + (n === 1 ? one : many || one + 's');

const said = {};
let summary = '';
reading.split('\n').forEach((raw) => {
  const line = raw.trim().replace(/^[-*\s]+/, '');
  const s = line.match(/^SUMMARY:\s*(.+)$/i);
  if (s) { summary = s[1].trim(); return; }
  const t = line.match(/^THEME\s+([a-z_]+)\s*:\s*(.+)$/i);
  if (t) said[t[1].toLowerCase()] = t[2].trim();
});

const rows = b.themes.map((t) => ({
  run_date: today,
  theme: t.label,
  comments: t.comments,
  likes: t.likes,
  share_pct: t.share_pct,
  top_quote: (t.quotes[0] || {}).text || '',
}));

const msg = [];
msg.push('*What buyers object to* - ' + today);
msg.push(
  b.objection_count + ' of ' + b.total_comments + ' comments (' + b.objection_share_pct +
  '%) across ' + b.videos_read + ' of ' + b.videos_asked + ' videos carried an objection.'
);
msg.push('');
if (summary) { msg.push(summary); msg.push(''); }

// The shares sum past 100 on purpose - one comment can raise three objections -
// and a percentage column that does not add up looks like a bug unless it says
// why.
msg.push('_Shares are of the objections, and a comment can raise more than one._');
msg.push('');

b.themes.forEach((t) => {
  msg.push(
    '*' + t.label + '* - ' + plural(t.comments, 'comment') + ', ' +
    plural(t.likes, 'like') + ', ' + t.share_pct + '% of objections'
  );
  if (said[t.key]) msg.push('    ' + said[t.key]);
  const q = t.quotes[0];
  if (q) msg.push('    _"' + q.text + '"_ (' + plural(q.likes, 'like') + ')');
});

if (b.alternatives.length) {
  msg.push('');
  msg.push('*Named when people said they left*');
  b.alternatives.forEach((a) =>
    msg.push('- ' + a.name + ' - ' + plural(a.mentions, 'mention') + ', ' + plural(a.likes, 'like'))
  );
}

if (b.mentions_of_you) {
  msg.push('');
  msg.push('_You were named in ' + b.mentions_of_you + ' of these comments._');
}

// Never silently. A video that returned nothing makes the remaining ones look
// like the whole picture.
if (b.failures.length || b.silent_videos.length) {
  msg.push('');
  msg.push('*Not read*');
  b.failures.forEach((f) => msg.push('- ' + (f.video_url || 'a video') + ': ' + f.reason));
  b.silent_videos
    .filter((id) => !b.failures.some((f) => String(f.video_url || '').includes(id)))
    .forEach((id) => msg.push('- ' + id + ': no comments came back'));
}
if (b.dropped_short) {
  msg.push('');
  msg.push('_' + plural(b.dropped_short, 'comment') + ' too short to classify, skipped._');
}

// A single item holding the rows array, and a Split Out below it. Handing this
// straight to Sheets writes one row whose columns are `message` and `rows` - a
// JSON blob where the description promised one row per theme.
return [{ json: { message: msg.join('\n'), rows, row_count: rows.length } }];
